"""Camera-guided robot episode. All object estimates come from RGB/depth.
The executed operations are recorded in history.jsonl; no reset is used.
Run with an operation JSON argument to take another step, or --replay to run
recorded operations against an already initialized episode.
"""
import sys,json,pathlib,time
import numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot, EpisodeOver
from scipy.spatial.transform import Rotation
OUT=pathlib.Path('/app/output'); RUNS=pathlib.Path('/app/runs')

def quat_matrix(q): return Rotation.from_quat(np.asarray(q)[[1,2,3,0]]).as_matrix()
def quat(R): return Rotation.from_matrix(R).as_quat()[[3,0,1,2]].tolist()
def pose_direction(xyz, closing, approach):
    x=np.asarray(closing,dtype=float);x/=np.linalg.norm(x)
    z=np.asarray(approach,dtype=float);z/=np.linalg.norm(z)
    y=np.cross(z,x);y/=np.linalg.norm(y);x=np.cross(y,z)
    return list(xyz)+quat(np.column_stack((x,y,z)))

def execute(r,op):
    typ=op['op']
    if typ=='obs': return r.get_obs(seconds=op.get('seconds',0),depth=True,video='none')
    o=r.get_obs(cameras=[],video='none');now=np.array(o.meta['proprio']['now']);q=now[:16].copy()
    if typ=='joint':
        target=np.asarray(op['target']);steps=max(2,int(op.get('duration',3)/.1)+1)
        a=np.linspace(q,target,steps);return r.submit('joint_position',a,dt=.1,video='none',depth=True,note=op.get('note',''))
    if typ=='grip':
        if 'right' in op:q[7]=op['right']
        if 'left' in op:q[15]=op['left']
        a=np.linspace(now[:16],q,11);a=np.vstack((a,np.repeat(q[None],10,axis=0)))
        return r.submit('joint_position',a,dt=.1,video='none',depth=True,note=op.get('note',''))
    if typ in ('move','ik'):
        targets={}
        for arm,offset in [('right',16),('left',23)]:
            if arm in op:
                value=op[arm];p=now[offset:offset+7].copy()
                if isinstance(value,dict):
                    if 'xyz' in value:p[:3]=value['xyz']
                    if 'quat' in value:p[3:]=value['quat']
                    if 'closing' in value:p=np.array(pose_direction(p[:3],value['closing'],value['approach']))
                else:p=np.asarray(value)
                targets['Gripper_Tip_'+('R' if arm=='right' else 'L')]=p.tolist()
        seed=np.r_[q[:7],q[8:15]]
        ik=r.ik(targets,seed=seed,max_iters=op.get('max_iters',250))
        print('IK',json.dumps(ik),flush=True)
        if typ=='ik':return None
        if not ik['ok']:raise RuntimeError('IK failed; no motion executed')
        q[:7]=ik['q'][:7];q[8:15]=ik['q'][7:]
        for arm,j in [('right',7),('left',15)]:
            if arm+'_grip' in op:q[j]=op[arm+'_grip']
        duration=op.get('duration',max(2,float(np.max(np.abs(q-now[:16])))/.35))
        steps=max(2,int(duration/.1)+1)
        if steps>100:raise ValueError('motion >10s; split into stages')
        a=np.linspace(now[:16],q,steps)
        a=np.vstack((a,np.repeat(q[None],min(10,100-len(a)),axis=0)))
        return r.submit('joint_position',a,dt=.1,video='none',depth=True,note=op.get('note',''))
    raise ValueError(typ)

def main():
    r=Robot()
    ops=[json.loads(x) for x in (OUT/'history.jsonl').read_text().splitlines()] if sys.argv[1]=='--replay' else [json.loads(sys.argv[1])]
    for op in ops:
        with (OUT/'history.jsonl').open('a') as f:
            if sys.argv[1]!='--replay':f.write(json.dumps(op)+'\n')
        res=execute(r,op)
        if res is not None:
            idx=len(list(RUNS.glob('step*')));dest=RUNS/f'step{idx:03d}';res.save(str(dest))
            (OUT/'latest.txt').write_text(str(dest))
            n=np.asarray(res.meta['proprio']['now'])
            print('RESULT',dest,'done',res.meta.get('done'),'reason',res.meta.get('reason'),'time_left',res.meta.get('time_left_s'),'tcp',n[16:30].round(5).tolist(),'grip',n[62:64].round(5).tolist(),'effort',n[64:].round(3).tolist(),flush=True)
            if res.done:break
if __name__=='__main__':main()
